#define CHECK(x) do {auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
static std::vector<double> readfixture(const char*name,size_t n){std::vector<double>x(n);std::ifstream f(std::string("/home/imo/HeCBench_julia/src/contract-julia/")+name,std::ios::binary);f.read((char*)x.data(),n*8);if(!f){fprintf(stderr,"fixture read failed\n");exit(2);}return x;}
template<class T>int study(){const int N=9,C=18,n=26244;auto td=readfixture("study_tensor_f64.bin",13122),ad=readfixture("study_adj_f64.bin",81),oracle=readfixture("oracle_f64.bin",n);std::vector<T>t(td.begin(),td.end()),a(ad.begin(),ad.end()),raw(n+64,T(-8192));T *dt,*da,*base;CHECK(cudaMalloc(&dt,t.size()*sizeof(T)));CHECK(cudaMalloc(&da,a.size()*sizeof(T)));CHECK(cudaMalloc(&base,raw.size()*sizeof(T)));CHECK(cudaMemcpy(dt,t.data(),t.size()*sizeof(T),cudaMemcpyHostToDevice));CHECK(cudaMemcpy(da,a.data(),a.size()*sizeof(T),cudaMemcpyHostToDevice));bool all=true;
for(int trial=1;trial<=5;trial++){std::fill(raw.begin(),raw.end(),T(-8192));CHECK(cudaMemcpy(base,raw.data(),raw.size()*sizeof(T),cudaMemcpyHostToDevice));contraction<<<103,256>>>(dt,da,base+32,n,N,C);CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int j=0;j<10;j++)contraction<<<103,256>>>(dt,da,base+32,n,N,C);CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;CHECK(cudaMemcpy(raw.data(),base,raw.size()*sizeof(T),cudaMemcpyDeviceToHost));std::vector<T>tr(t.size()),ar(a.size());CHECK(cudaMemcpy(tr.data(),dt,t.size()*sizeof(T),cudaMemcpyDeviceToHost));CHECK(cudaMemcpy(ar.data(),da,a.size()*sizeof(T),cudaMemcpyDeviceToHost));bool ok=tr==t&&ar==a;double err=0,rel=0;for(int i=0;i<n;i++){double v=raw[32+i],e=std::abs(v-oracle[i]);ok&=std::isfinite(v)&&e==0;err=std::max(err,e);rel=std::max(rel,e/std::max(std::abs(oracle[i]),2.220446049250313e-16));}for(int j=0;j<32;j++)ok&=raw[j]==T(-8192)&&raw[32+n+j]==T(-8192);all&=ok;std::vector<double>artifact(tr.begin(),tr.end());artifact.insert(artifact.end(),ar.begin(),ar.end());artifact.insert(artifact.end(),{9,18,18,double(8*sizeof(T))});artifact.insert(artifact.end(),raw.begin()+32,raw.begin()+32+n);artifact.insert(artifact.end(),raw.begin(),raw.begin()+32);artifact.insert(artifact.end(),raw.begin()+32+n,raw.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)artifact.data(),artifact.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":26308,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"full18case_contraction_kernel_launch_loop_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":10,\"source_cases\":18,\"precision_bits\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,sec,ok?"true":"false",err,rel,int(8*sizeof(T)),path.c_str(),artifact.size());}CHECK(cudaFree(dt));CHECK(cudaFree(da));CHECK(cudaFree(base));return all?0:1;}
int main(){return std::string(getenv("STUDY_DTYPE")?getenv("STUDY_DTYPE"):"32")=="32"?study<float>():study<double>();}
